insert into kafaa_engine_cards (id, engine_surface, module, route, feature, title_en, title_ar, purpose_en, purpose_ar, owner_en, owner_ar, inputs_used, inputs_excluded, scoring_functions, weight_keys, output_en, output_ar, oversight_en, oversight_ar, limitations_en, limitations_ar, opt_out, version, last_changed_at, last_change_id, sources, sort, kernel_surface, ranks, fairness_metric, fairness_none) values
('critical_attention', 'skills', 'M35', '/workforce/critical-skills', 'FS50', 'Critical skills register: attention order', 'سجل المهارات الحرجة: ترتيب الأولوية', 'Orders the rows of the critical future-skills register by how much they need the HR director''s attention: progress off track or at risk, an overdue quarterly review, no active gap plan and the forecast gap.', 'يرتّب صفوف سجل المهارات المستقبلية الحرجة حسب حاجتها إلى انتباه مدير الموارد البشرية: تقدّم خارج المسار أو معرّض للخطر، ومراجعة ربعية متأخرة، وغياب خطة فجوة نشطة، وفجوة التوقع.', 'HR authority, CHCO office (role card)', 'سلطة الموارد البشرية، مكتب الرئيس التنفيذي لرأس المال البشري (بطاقة دور)', '[{"key":"critical_skills","en":"Register rows: target level and yearly targets, the build, buy, borrow or bot decision, KPIs and review dates","ar":"صفوف السجل: المستوى المستهدف والأهداف السنوية وقرار البناء أو الشراء أو الاستعارة أو الأتمتة والمؤشرات ومواعيد المراجعة"},{"key":"person_skills","en":"Counts of recorded skill states per skill and level (aggregated, suppressed under 10 people)","ar":"أعداد حالات المهارات المسجلة لكل مهارة ومستوى (مجمّعة، ومحجوبة دون 10 أشخاص)"},{"key":"skill_gap_plans","en":"Active FS04 gap plans linked to the register row","ar":"خطط الفجوات النشطة (FS04) المرتبطة بصف السجل"},{"key":"skill_forecasts","en":"The forecast gap from the released skill forecast","ar":"فجوة التوقع من إصدار توقعات المهارات المعتمد"}]'::jsonb, array['gender','nationality_flag','age']::text[], array['src/modules/m35/critical.ts#attentionOf','src/modules/m35/critical.ts#criticalBoard','sql:kafaa_crs_board_core']::text[], '{}'::text[], 'Register rows (skills, never people) in attention order, each with its reasons; progress based on fewer than 10 people is suppressed.', 'صفوف السجل (مهارات وليست أشخاصاً) بترتيب الأولوية مع أسباب كل منها؛ ويُحجب التقدّم القائم على أقل من 10 أشخاص.', 'The HR director reviews every adopted row each quarter and decides the response; the order only suggests where to look first. It never decides anything on its own: a person reads the reasons and chooses.', 'يراجع مدير الموارد البشرية كل صف معتمد كل ربع سنة ويقرّر الاستجابة؛ ويقترح الترتيب فقط من أين يبدأ النظر. لا يقرّر شيئاً بمفرده: يقرأ الشخص الأسباب ويختار.', 'Progress is computed from recorded skill states and is SIMULATED in this demo. It ranks skills, not people.', 'يُحتسب التقدّم من حالات المهارات المسجلة وهو محاكى في هذا العرض. يرتّب المهارات لا الأشخاص.', false, 1, '2026-10-11T00:00:00Z', null, '[{"label":"TechWolf · Workday customer story (skills inference with governance)","url":"https://www.techwolf.ai/customer-stories/workday","as_of":"2026-10-11"},{"label":"European Commission · EU AI Act Article 4 AI-literacy repository","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","as_of":"2026-10-11"}]'::jsonb, 32, 'rules', 'options', null, 'no_outcome'),
('outlook_automation', 'skills', 'M07', '/workforce/skills-outlook', 'FS52', 'Skills outlook: automation exposure by family', 'آفاق المهارات: التعرض للأتمتة حسب العائلة', 'Orders skill families by the share of their task hours that the task layer marks as AI-assisted or partly automated, at the adoption level chosen on the page.', 'يرتّب عائلات المهارات حسب حصة ساعات مهامها التي تعدّها طبقة المهام مدعومة بالذكاء الاصطناعي أو مؤتمتة جزئياً، عند مستوى التبني المختار في الصفحة.', 'Future workforce lead (role card)', 'مسؤول القوى العاملة المستقبلية (بطاقة دور)', '[{"key":"jta_tasks","en":"Task hours per role and each task''s AI change horizon from the job and task analysis (FS06)","ar":"ساعات المهام لكل دور وأفق تغيّر كل مهمة بالذكاء الاصطناعي من تحليل الوظائف والمهام (FS06)"},{"key":"ai_capability_levels","en":"Published AI capability levels and exposure references per task","ar":"مستويات قدرات الذكاء الاصطناعي المنشورة ومراجع التعرض لكل مهمة"},{"key":"skill_outlooks","en":"The outlook assumptions, including the adoption level chosen on the page","ar":"افتراضات الآفاق، ومنها مستوى التبني المختار في الصفحة"}]'::jsonb, array['gender','nationality_flag','age']::text[], array['src/modules/m07/outlook.ts#rankAutomation','src/modules/m07/outlook.ts#automationProfile','sql:kafaa_so_auto_profile']::text[], '{}'::text[], 'Families in order of exposure with the demand change at the chosen adoption, each with its reasons; every number is SIMULATED and families under 10 people are suppressed.', 'العائلات بترتيب التعرض مع تغيّر الطلب عند التبني المختار وأسباب كل منها؛ وكل رقم محاكى، وتُحجب العائلات التي تضم أقل من 10 أشخاص.', 'HR planners set the adoption assumption; nothing changes a role, a headcount or a person. It never decides anything on its own: a person reads the reasons and chooses.', 'يحدّد مخططو الموارد البشرية افتراض التبني؛ ولا يغيّر شيء دوراً أو عدداً أو شخصاً. لا يقرّر شيئاً بمفرده: يقرأ الشخص الأسباب ويختار.', 'Exposure comes from the task analysis and published capability levels, not from observed automation. It ranks families, not people.', 'يأتي التعرض من تحليل المهام ومستويات القدرات المنشورة، لا من أتمتة مرصودة. يرتّب العائلات لا الأشخاص.', false, 1, '2026-10-11T00:00:00Z', null, '[{"label":"TechWolf · Workday customer story (skills inference with governance)","url":"https://www.techwolf.ai/customer-stories/workday","as_of":"2026-10-11"},{"label":"European Commission · EU AI Act Article 4 AI-literacy repository","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","as_of":"2026-10-11"}]'::jsonb, 33, 'rules', 'options', null, 'no_outcome'),
('aps_next', 'recommend', 'M33', '/my/core-skills/problem-solving', 'FS58', 'Problem-solving practice: suggested next scenario', 'تدريب حل المشكلات: السيناريو المقترح التالي', 'Suggests the published scenario I have practised least, rotated so that colleagues do not all get the same one, with the theme it trains.', 'يقترح السيناريو المنشور الذي تدرّبت عليه أقل من غيره، مع تدوير حتى لا يحصل الزملاء جميعاً على السيناريو نفسه، مع الموضوع الذي يدرّبه.', 'Training Manager (role card)', 'مدير التدريب (بطاقة دور)', '[{"key":"aps_scenarios","en":"Published practice scenarios with their theme","ar":"سيناريوهات التدريب المنشورة مع موضوعها"},{"key":"aps_attempts","en":"My own practice runs (how often I practised each scenario)","ar":"محاولاتي التدريبية (عدد مرات تدرّبي على كل سيناريو)"}]'::jsonb, array['gender','nationality_flag','age']::text[], array['src/modules/m33/aps.ts#pickScenario','src/modules/m33/aps.ts#nextReasons','sql:kafaa_aps_pick','sql:kafaa_aps_next_reasons']::text[], '{}'::text[], 'One suggested scenario with its reasons; any other published scenario can be chosen.', 'سيناريو واحد مقترح مع أسبابه؛ ويمكن اختيار أي سيناريو منشور آخر.', 'Scenarios are written and published by the training manager; results are mine and never gate a qualification. It never decides anything on its own: a person reads the reasons and chooses.', 'يكتب مدير التدريب السيناريوهات وينشرها؛ والنتائج لي ولا تكون شرطاً لأي مؤهل. لا يقرّر شيئاً بمفرده: يقرأ الشخص الأسباب ويختار.', 'It ranks content, not people, and only among published scenarios.', 'يرتّب المحتوى لا الأشخاص، ومن بين السيناريوهات المنشورة فقط.', false, 1, '2026-10-11T00:00:00Z', null, '[{"label":"TechWolf · Workday customer story (skills inference with governance)","url":"https://www.techwolf.ai/customer-stories/workday","as_of":"2026-10-11"},{"label":"European Commission · EU AI Act Article 4 AI-literacy repository","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices","as_of":"2026-10-11"}]'::jsonb, 34, 'rules', 'content', null, 'content')
